const urlsData = ["app2.unifans.io","app.unifans.io","app.yinliquan.app"];

function putUrl(n){
	const {java,source} = this;
	let urlData = {index:(n?n:0)};
 let data = [];
 urlsData.forEach((x,i)=>{
		    data.push({
		    	     t:x.replace(/https?:\/\//,''),
		    	     u:x
		    	})
    });
    urlData.data = data;
    source.setVariable(JSON.stringify(urlData));    
}

function getUrl(){
    const {source} = this;
    	let s = String(source.getVariable());
    if(!s){
    	     this.putUrl();
        	 s = String(source.getVariable());
    	}
    let urlData = JSON.parse(s);
    let index = urlData.index;
    let data = urlData.data;
	return data[index].t.replace(/\/$/,'');	
}

