@js:(function(){
var s = String(result||'');
s = s.replace(/(一秒记住[^\n]{0,40}|www\.cncjbz\.com[^\n]{0,40}|海棠文学城转载收集[^\n]{0,60}|请记住本书首发域名[^\n]{0,40})/gi,'');
var dict = {"sE": "色", "hsE": "色", "Ye": "液", "nV": "女", "g0ng": "宫", "T": "体", "Si": "死", "X": "性", "W": "污", "r0U": "肉", "r0u": "肉", "yu": "欲", "m0": "摸", "C": "操", "h": "黄", "g": "干", "b": "比", "Y": "影", "Ai": "爱", "x": "胸", "r": "乳", "y": "硬", "x1": "吸", "cHa": "插", "Sh": "湿", "bA0": "苞", "GU": "股", "Gu": "股", "nEnG": "嫩", "T1aN": "舔", "SHeNY1N": "呻吟", "rUjiaNg": "乳尖", "x1ShUn": "吸吮", "GinJiNg": "精", "JiNg": "精", "yAn": "阳", "Shu": "湿"};
var DJ = /[\u4e00-\u9fff]/;
var confirmed = {};
s.replace(/[A-Za-z0-9]{1,20}/g, function(run, off){
  if (dict[run] === undefined) return run;
  var pre = off > 0 ? s.charAt(off-1) : '';
  var post = off + run.length < s.length ? s.charAt(off + run.length) : '';
  if (DJ.test(pre) || DJ.test(post)) confirmed[run] = true;
  return run;
});
function engGuard(run, off){
  var L = off > 0 ? s.charAt(off-1) : '';
  var R = off + run.length < s.length ? s.charAt(off + run.length) : '';
  var isLet = function(c){ return c && /[A-Za-z]/.test(c); };
  if (R === '-' && isLet(s.charAt(off + run.length + 1))) return true;
  if (L === '-' && isLet(s.charAt(off - 2))) return true;
  var wl = s.slice(Math.max(0, off-10), off);
  var wr = s.slice(off + run.length, Math.min(s.length, off + run.length + 10));
  if (/[A-Za-z]{2}/.test(wl) && /[A-Za-z]{2}/.test(wr)) return true;
  return false;
}
s = s.replace(/[A-Za-z0-9]{1,20}/g, function(run, off){
  var dec = dict[run];
  if (dec === undefined) return run;
  var pre = off > 0 ? s.charAt(off-1) : '';
  var post = off + run.length < s.length ? s.charAt(off + run.length) : '';
  var nearCjk = DJ.test(pre) || DJ.test(post);
  if (!nearCjk && !confirmed[run]) return run;
  if (engGuard(run, off)) return run;
  return dec;
});
s = s.replace(/&nbsp;/g,' ').replace(/&ensp;|&emsp;/g,' ').replace(/&amp;/g,'&');
s = s.replace(/<\s*br\s*\/?>/gi,'\n').replace(/<\/?p[^>]*>/gi,'\n');
return s;
})()

